from pathlib import Path
import re
p=Path('index.html');s=p.read_text(encoding='utf-8')
s=re.sub(r'<title>.*?</title>','<title>JEREMIE Studio</title>',s,count=1,flags=re.S)
s=re.sub(r'\n?  /\* JEREMIE SAFE PATCH START \*/.*?/\* JEREMIE SAFE PATCH END \*/\n?','\n',s,flags=re.S)
s=re.sub(r'\n?<script id="jeremie-safe-patch">.*?</script>\n?','\n',s,flags=re.S)
css=r'''  /* JEREMIE SAFE PATCH START */
  :root{--jeremie-accent:linear-gradient(135deg,#ff3d2b 0%,#e32b79 36%,#c12d98 66%,#9336d0 100%)}
  .filter-btn{font-size:clamp(40.5px,6.48vw,108px)!important;font-weight:800!important;line-height:.86!important}.filter-btn.active,.filter-btn:hover,.filter-btn:focus-visible,.menu-overlay .menu-link:hover,.menu-overlay .menu-link:focus-visible,.menu-overlay .menu-link.active,.menu-overlay .menu-nav a:hover,.menu-overlay .menu-nav a:focus-visible,.menu-overlay .menu-nav a.active{color:transparent!important;background:var(--jeremie-accent)!important;-webkit-background-clip:text!important;background-clip:text!important;-webkit-text-fill-color:transparent!important}
  .burger{position:fixed!important;top:26px!important;right:40px!important;z-index:99999!important;width:42px!important;height:42px!important;border:1px solid currentColor!important;background:transparent!important;display:flex!important;align-items:center!important;justify-content:center!important;flex-direction:column!important;gap:7px!important;padding:0!important;color:#777!important}.burger span{display:block!important;width:20px!important;height:2px!important;background:currentColor!important;transition:transform .48s cubic-bezier(.16,.8,.24,1)!important}.burger span:nth-child(n+3){display:none!important}.burger.open span:first-child{transform:translateY(4.5px) rotate(45deg)!important}.burger.open span:nth-child(2){transform:translateY(-4.5px) rotate(-45deg)!important}.menu-close{display:none!important}html.menu-open,body.menu-open{overflow:hidden!important}
  .menu-overlay.open hr{display:none!important}.menu-overlay.open [class*="footer"],.menu-overlay.open [class*="bottom"],.menu-overlay.open [class*="foot"],.menu-overlay.open [class*="meta"]{border:0!important;box-shadow:none!important}
  .global-theme-toggle{position:fixed!important;right:40px!important;bottom:72px!important;z-index:390!important;width:auto!important;height:42px!important;padding:0!important;border:0!important;background:transparent!important;color:#777!important;display:flex!important;align-items:center!important;gap:12px!important;cursor:pointer!important;font-family:inherit!important}.global-theme-toggle .theme-label{display:block!important;font-size:18px!important;font-weight:800!important;line-height:1!important;white-space:nowrap!important;color:currentColor!important}.global-theme-toggle .theme-icon-wrap{position:relative!important;width:42px!important;height:42px!important;flex:0 0 42px!important;transform:rotate(0);transition:transform .55s cubic-bezier(.16,.8,.24,1)!important}body.inverted .global-theme-toggle .theme-icon-wrap{transform:rotate(90deg)!important}.global-theme-toggle svg{width:42px!important;height:42px!important;display:block!important}.global-theme-toggle .theme-gear{fill:none!important;stroke:currentColor!important;stroke-width:1.6!important;stroke-linejoin:round!important}.global-theme-toggle .theme-sun,.global-theme-toggle .theme-moon{transform-box:fill-box;transform-origin:center;transition:opacity .34s ease,transform .5s cubic-bezier(.16,.8,.24,1)!important}.global-theme-toggle .theme-sun{opacity:1;transform:scale(1)}.global-theme-toggle .theme-moon{opacity:0;transform:rotate(-35deg) scale(.72)}body.inverted .global-theme-toggle .theme-sun{opacity:0;transform:rotate(35deg) scale(.72)}body.inverted .global-theme-toggle .theme-moon{opacity:1;transform:rotate(-90deg) scale(1)}body.inverted .global-theme-toggle{color:#777!important}body.inverted .hero-title-img{filter:invert(1) hue-rotate(180deg) brightness(1.02) contrast(.96)}
  .work-detail-overlay{position:fixed!important;inset:0!important;z-index:100000!important;background:#151515!important;opacity:0;visibility:hidden;pointer-events:none;overflow-y:auto!important;transition:opacity .35s,visibility .35s!important}.work-detail-overlay.open{opacity:1!important;visibility:visible!important;pointer-events:auto!important}.work-detail-stage{min-height:100%;padding:76px 24px 96px!important;display:flex!important;justify-content:center!important}.work-detail-image{display:block!important;width:min(1180px,calc(100vw - 160px))!important;height:auto!important;object-fit:contain!important;opacity:0;transform:translateY(18px)!important;box-shadow:0 30px 90px rgba(0,0,0,.34)!important;transition:.5s!important}.work-detail-overlay.open .work-detail-image{opacity:1!important;transform:none!important}.work-detail-close{position:fixed!important;top:26px!important;right:40px!important;z-index:100002!important;width:42px!important;height:42px!important;border:1px solid #f3f1ea!important;background:#151515!important;color:#f3f1ea!important;display:flex!important;align-items:center!important;justify-content:center!important}.work-detail-close span{position:absolute!important;width:20px!important;height:1.5px!important;background:currentColor!important}.work-detail-close span:first-child{transform:rotate(45deg)!important}.work-detail-close span:last-child{transform:rotate(-45deg)!important}html.detail-open,body.detail-open{overflow:hidden!important}body.detail-open .burger,body.detail-open .global-theme-toggle{opacity:0!important;visibility:hidden!important;pointer-events:none!important}
  @media(max-width:700px){.burger{top:20px!important;right:20px!important}.global-theme-toggle{right:20px!important;bottom:56px!important;gap:9px!important}.global-theme-toggle .theme-label{font-size:15px!important}.filter-btn{font-size:clamp(36px,12vw,58px)!important}.work-detail-image{width:calc(100vw - 24px)!important}.work-detail-close{top:20px!important;right:20px!important}}
  /* JEREMIE SAFE PATCH END */'''
s=s.replace('</style>',css+'\n</style>',1)
js=r'''<script id="jeremie-safe-patch">(()=>{const ready=f=>document.readyState==='loading'?document.addEventListener('DOMContentLoaded',f):f();ready(()=>{document.title='JEREMIE Studio';const body=document.body,root=document.documentElement,menu=document.querySelector('.menu-overlay'),oldBurger=document.querySelector('.burger'),menuClose=document.querySelector('.menu-close');const unlock=()=>{body.classList.remove('menu-open');root.classList.remove('menu-open');body.style.overflow='';root.style.overflow=''};unlock();let burger=oldBurger;if(oldBurger&&menu){burger=oldBurger.cloneNode(true);burger.innerHTML='<span></span><span></span>';oldBurger.replaceWith(burger);document.body.appendChild(burger);const setMenu=o=>{menu.classList.toggle('open',o);burger.classList.toggle('open',o);if(o){body.classList.add('menu-open');root.classList.add('menu-open')}else unlock()};setMenu(false);burger.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();setMenu(!menu.classList.contains('open'))});document.querySelectorAll('.menu-link,.menu-nav a').forEach(a=>a.addEventListener('click',()=>setMenu(false)))}if(menuClose)menuClose.setAttribute('aria-hidden','true');const bs=[...document.querySelectorAll('.theme-toggle')];let theme=document.getElementById('themeToggle')||bs[0];document.querySelectorAll('.global-theme-toggle').forEach(x=>{if(x!==theme)x.remove()});bs.forEach(x=>{if(x!==theme)x.remove()});if(theme){theme.classList.add('global-theme-toggle');theme.innerHTML=`<span class="theme-label">Light Mode</span><span class="theme-icon-wrap"><svg viewBox="0 0 42 42" aria-hidden="true"><path class="theme-gear" d="M18.2 3.8h5.6l1 3.8 3.55 1.48 3.38-1.98 3.96 3.96-1.98 3.38 1.48 3.55 3.81 1v5.6l-3.81 1-1.48 3.55 1.98 3.38-3.96 3.96-3.38-1.98-3.55 1.48-1 3.81h-5.6l-1-3.81-3.55-1.48-3.38 1.98-3.96-3.96 1.98-3.38-1.48-3.55-3.81-1v-5.6l3.81-1 1.48-3.55-1.98-3.38 3.96-3.96 3.38 1.98 3.55-1.48 1-3.8Z"/><g class="theme-sun" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round"><circle cx="21" cy="21" r="4.3"/><path d="M21 10.2v3M21 31.8v-3M10.2 21h3M31.8 21h-3M13.4 13.4l2.1 2.1M28.6 28.6l-2.1-2.1M28.6 13.4l-2.1 2.1M13.4 28.6l2.1-2.1"/></g><g class="theme-moon" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M25.9 25a8.2 8.2 0 0 1-9.8-9.8A7.6 7.6 0 1 0 25.9 25Z"/></g></svg></span>`;document.body.appendChild(theme);const label=theme.querySelector('.theme-label'),sync=()=>label.textContent=body.classList.contains('inverted')?'Dark Mode':'Light Mode';sync();new MutationObserver(sync).observe(body,{attributes:true,attributeFilter:['class']})}document.querySelectorAll('#workDetailOverlay').forEach(x=>x.remove());const overlay=document.createElement('div');overlay.id='workDetailOverlay';overlay.className='work-detail-overlay';overlay.innerHTML='<button class="work-detail-close" type="button"><span></span><span></span></button><div class="work-detail-stage"><img class="work-detail-image" src="work_01_detail.png" alt="Grand 11st project detail"></div>';document.body.appendChild(overlay);const close=overlay.querySelector('.work-detail-close');let sy=0;const openD=()=>{sy=scrollY;if(menu)menu.classList.remove('open');if(burger)burger.classList.remove('open');unlock();body.classList.add('detail-open');root.classList.add('detail-open');overlay.classList.add('open')},closeD=()=>{overlay.classList.remove('open');body.classList.remove('detail-open');root.classList.remove('detail-open');requestAnimationFrame(()=>scrollTo(0,sy))};const grid=document.querySelector('.grid');if(grid)grid.addEventListener('click',e=>{const t=e.target.closest('.tile');if(t&&t===grid.querySelector('.tile')){e.preventDefault();openD()}});close.addEventListener('click',closeD);document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(overlay.classList.contains('open'))closeD()}})})})();</script>'''
s=s.replace('</body>',js+'\n</body>',1);p.write_text(s,encoding='utf-8')
